import { FileUpload } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
function imageFile() {
  return new File(
    [
      `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200"><rect width="320" height="200" fill="#bedcf0"/><path d="M40 150 160 40l120 110" fill="#fff8f2" stroke="#bd4b30" stroke-width="12"/></svg>`,
    ],
    'composicao.svg',
    { type: 'image/svg+xml', lastModified: 2 },
  );
}
function documentFile() {
  return new File(['comprovante'], 'sample-document.pdf', {
    type: 'application/pdf',
    lastModified: 1,
  });
}
function Preset({
  kind = 'document',
  ...props
}: {
  kind?: 'document' | 'image';
} & React.ComponentProps<typeof FileUpload>) {
  const [files, setFiles] = useState(() => [
    kind === 'image' ? imageFile() : documentFile(),
  ]);
  return <FileUpload {...props} files={files} onFilesChange={setFiles} />;
}
export function Example() {
  const args: Pick<ComponentProps<typeof FileUpload>, 'accept' | 'maxSize'> = {
    accept: 'image/*,.pdf',
    maxSize: 10 * 1024 * 1024,
  };
  return <Preset {...args} />;
}

